"""Build a detailed, reviewable editorial change record."""
from pathlib import Path
import json,html
from weasyprint import HTML
R=Path(__file__).resolve().parents[1];changes=json.loads((R/'ebook/editorial-changes.json').read_text());v=json.loads((R/'ebook/verification.json').read_text());font=(R/'ebook/fonts/NotoSerifCJKsc-Regular.otf').as_uri()
css=f'''@font-face{{font-family:Report;src:url("{font}")}}@page{{size:A4;margin:21mm 22mm 22mm;@top-center{{content:"在我们理解大脑之前 · 编辑审校";font:8pt Report;color:#667465}}@bottom-center{{content:counter(page);font:9pt Report;color:#667465}}}}body{{font:10.5pt/1.8 Report;color:#26372d}}h1{{font-size:25pt;font-weight:normal;line-height:1.5;margin:5mm 0 6mm}}h2{{font-size:13pt;font-weight:normal;line-height:1.7;break-after:avoid;margin:8mm 0 3mm}}p{{margin:0 0 4mm;orphans:3;widows:3}}.cover{{break-after:page;padding-top:28mm}}.kicker,.label{{font-size:8.5pt;color:#6a7868;letter-spacing:1pt}}.cover p{{margin-top:6mm}}.change{{break-inside:avoid;border-top:.5pt solid #d8ddcf;padding-top:2mm}}.reason{{color:#435642}}blockquote{{font-size:9.5pt;line-height:1.85;padding:3mm 4mm;margin:0 0 4mm;border-left:2pt solid #c1c6b7;background:#f5f4ef}}.after{{border-color:#688c6b;background:#f0f4ed}}a{{color:#45644d;text-decoration:none}}.section{{break-before:page}}li{{margin:0 0 3mm}}'''
body='''<section class="cover"><p class="kicker">一心问道 · 六部二十四章</p><h1>在我们理解大脑之前<br>编辑审校与界面修订记录</h1><p>2026年10月12日 · 编辑修订版</p><p>本次按“明确错误优先、局部修订”的范围处理：修正时间与人物记忆的矛盾、不存在的章节指称、重复说明和生成过程残留；少量文字调整集中在过密的结论句。保留六部二十四章、作者署名、情节走向、81幅插图和288条章节参考文献。没有以特定在世作家的个人文风重写全书。</p><h2>本次明确处理</h2><p>叙事时间矛盾、演讲重复、章节指称错误、用语残留、过期插图提示，以及阅读进度和发布流程问题。</p><h2>界面与书籍</h2><p>首页扩展为完整图书介绍页：封面与详细故事简介、两条叙事线索、六部导读、24章的主题与情节简介、三段精选图文试读，以及在线阅读、笔记、设置和离线下载说明。正文页统一字体、图注和参考文献排版，保留原有阅读功能。新增自托管中文字体子集，保留字体许可证。</p></section>'''
for i,c in enumerate(changes,1):
 label=f"第{c['chapter']}章" if isinstance(c['chapter'],int) else c['chapter']
 body+=f'<section class="change"><h2>{i:02d} · {html.escape(label)} · {html.escape(c["kind"])}</h2><p class="reason">{html.escape(c["reason"])}</p><p class="label">修改前</p><blockquote>{html.escape(c["before"])}</blockquote><p class="label">修改后</p><blockquote class="after">{html.escape(c["after"])}</blockquote></section>'
body+=f'''<section class="section"><h1>检查与交付说明</h1><h2>完整性与功能</h2><p>电子书更新为{v['pages']}页。全文、各章说明、参考文献与图注经文字提取核对，无缺失；81幅正文插图与1张封面均保留，30个书签与24章章节开头对应。页面边界检查未发现溢出，中文字体嵌入。</p><p>网页本地链接、6组目录、24章入口、段落锚点和81幅图均检查通过。阅读器以保存进度、书签位置、首次进入与夜间主题等场景完成脚本测试。网页另做桌面与手机尺寸的静态排版校样；此校样不等同全部真实设备测试。</p><h2>审校范围与保留内容</h2><p>本次没有把全部科学史书目重新当作一项文献系统综述核验。重点查证了第一章颁奖及演讲时间等明确疑点；能由官方记录支持的细节予以保留。小说对白和人物动作仍属虚构。</p><p>没有删掉科学史说明、改写结尾或清除原有读者笔记。若旧划线恰好落在修订句子内，可能需要重新定位；笔记文字仍保留在原浏览器。</p><h2>核查线索</h2><ul><li><a href="https://www.nobelprize.org/uploads/2018/06/cajal-lecture.pdf">卡哈尔 Nobel Lecture，1906-12-12</a></li><li><a href="https://www.nobelprize.org/uploads/2018/06/golgi-lecture.pdf">高尔基 Nobel Lecture，1906-12-11</a></li><li><a href="https://www.nobelprize.org/ceremony/childhood-memories-of-early-nobel-ceremonies-and-laureates/">诺贝尔奖早期典礼回忆：礼服等细节</a></li><li><a href="https://www.nobelprize.org/prizes/medicine/1932/sherrington/speech/">谢灵顿1932年宴会致辞</a></li><li><a href="https://www.uzh.ch/dam/jcr:00000000-7705-3087-ffff-ffffdcf813a1/hess.pdf">苏黎世大学赫斯档案</a></li></ul><h2>版本来源</h2><p>以2026年10月12日主分支为修订基础，小说全文保持六部二十四章。完整修改记录另见仓库 ebook/EDITORIAL.md。</p></section>'''
HTML(string=f'<!doctype html><html lang="zh"><meta charset="utf-8"><title>编辑审校与界面修订记录</title><style>{css}</style><body>{body}</body></html>').write_pdf(R/'docs/downloads/brain-novel-editorial-report.pdf',pdf_tags=True)
print('Editorial report regenerated')
